INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-04' FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Post-issuance electronic reporting via the BIR''s Electronic Invoicing/Receipting System (EIS) -- Phase 1 mandatory from 31 December 2026', 'This deep-dive page reflects publicly available BIR guidance and industry reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. This mandate has a documented history of moving -- its 2022 pilot paused for roughly two years, and the Phase 1 deadline has already shifted once, from March 2026 to December 2026 -- so confirm the current date and requirements directly with the BIR or a Philippine tax adviser before relying on this page for compliance decisions.', 'The legal basis dates to 2018: the TRAIN Law (RA 10963) amended the National Internal Revenue Code to authorize e-invoicing and near-real-time electronic sales reporting for large taxpayers and exporters. Revenue Regulations No. 8-2022 (RR 8-2022) issued the first implementing rules and launched a voluntary pilot with 100 selected large taxpayers ("LT100") from 1 July 2022 -- but technical and capacity problems forced the BIR to pause the program later that year, and it stayed stalled for roughly two years. RR 11-2025 formally resumed and expanded the mandate under the CREATE MORE law in February 2025, setting a 14 March 2026 deadline for a broadened taxpayer list -- large taxpayers, e-commerce and digital businesses of any size, exporters, and CAS/POS users among them. That deadline was itself superseded before it arrived: RR 26-2025 (October 2025) pushed Phase 1 to 31 December 2026, described elsewhere as e-invoicing becoming mandatory from 1 January 2027. A second phase extending the mandate to remaining medium and small businesses has no confirmed date yet -- it depends on the BIR''s own systems being ready.', 'A compliant e-invoice must use a structured, machine-readable data format capable of electronic transmission to the BIR -- PDFs and other non-structured formats no longer qualify once Phase 1 applies. The BIR has not published a single fixed technical schema the way UBL or Peppol define one elsewhere in this tracker; issuance runs through BIR-permitted Computerized Accounting Systems (CAS) or point-of-sale systems, or the EIS portal directly.', 'Phase 1 covers Large Taxpayers, e-commerce and digital-platform businesses of any size, exporters with VAT zero-rated sales, users of Computerized Accounting Systems or POS systems with e-invoicing capability, and Registered Business Enterprises holding tax incentives. Micro enterprises (annual gross sales below PHP 3 million) are exempt but may opt in voluntarily for cost-deduction incentives. Medium and small businesses outside these categories fall under an unscheduled Phase 2.', 'Getting ready means confirming whether you''re already in Phase 1 scope (the list is broader than "large taxpayers" alone), moving off PDF invoicing onto a genuinely structured format, keeping your CAS/POS BIR permit current, and building in a buffer given this mandate''s documented history of moving.', 'The Philippines backs its e-invoicing rules with a genuinely tiered enforcement structure under the NIRC as amended by the TRAIN Law and RR 13-2021: fines and imprisonment for failing to issue a required e-invoice, a steep per-day-or-percentage penalty (with possible permanent closure after 180 days) for failing to transmit sales data to the BIR, and separately harsh sanctions for deliberately using sales-suppression software.', 'The Philippines'' Bureau of Internal Revenue operates a post-issuance reporting model under its Electronic Invoicing/Receipting System (EIS): an invoice is legally valid the moment it reaches the buyer, with sales-data transmission to the BIR a separate duty rather than a precondition for validity. The legal basis dates to 2018''s TRAIN Law, but the operative mandate has a documented history of slipping -- a 2022 pilot paused for roughly two years, and Revenue Regulations No. 26-2025 has already pushed the current Phase 1 deadline from March 2026 to 31 December 2026 for Large Taxpayers, e-commerce businesses of any size, exporters, and CAS/POS users. Non-compliance carries real consequences: fines and imprisonment for failing to issue a required invoice (NIRC Section 264), and separately, the higher of 0.1% of prior-year net income or PHP 10,000 per day for failing to transmit sales data, with permanent business closure possible after 180 days (Section 264-A).', '🇵🇭' FROM countries WHERE name_en = 'Philippines';
