INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Format", "Structured, machine-readable data format -- PDFs and other non-structured formats no longer qualify once Phase 1 applies"], ["Reporting platform", "Electronic Invoicing/Receipting System (EIS), migrating toward the Electronic Sales Reporting System (ESRS)"], ["Legal basis", "NIRC Sections 237/237-A as amended by the TRAIN Law (RA 10963), implemented via RR 8-2022, RR 11-2025, and RR 26-2025"], ["Governing body", "Bureau of Internal Revenue (BIR)"]]', 'Unlike UBL or Peppol elsewhere in this tracker, the BIR has not published one single fixed technical schema -- confirm the current specification directly with the BIR or an accredited service provider before building to it.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["Taxpayer ID", "Taxpayer Identification Number (TIN)"], ["Registration", "Enrollment via the EIS portal (eis.bir.gov.ph) or an accredited CAS/POS provider"], ["Governing body", "Bureau of Internal Revenue (BIR)"], ["Certification", "Computerized Accounting Systems (CAS) and POS systems need a current BIR permit-to-use"]]', 'An outdated or missing CAS/POS permit is its own compliance gap, separate from the invoicing format itself.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content', '[["Core fields", "Issuer/buyer TIN, invoice type, date, itemized sales, VAT breakdown"], ["Structured format required", "PDFs and other non-structured formats no longer qualify as valid e-invoices once Phase 1 applies"], ["Retention", "Standard BIR bookkeeping retention rules apply -- confirm the current period with a tax adviser"], ["Permit-to-use", "Computerized systems require a prior BIR permit before issuing electronically"]]', 'The retention and permit requirements sit on top of the invoicing mandate itself -- both are separate, ongoing BIR obligations, not one-time setup steps.', NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The issue-then-report flow', 'A Philippine e-invoice moves through this sequence once Phase 1 applies -- note this is reporting, not clearance:', 'The invoice is already legally complete once it reaches the buyer -- the BIR is not asked to approve it first, unlike the clearance-model mandates covered elsewhere in this tracker (Colombia, Argentina, Jordan).');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Invoice issued in structured, machine-readable format');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Delivered to buyer -- valid immediately, no BIR pre-approval needed');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 2, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Sales data transmitted to the BIR (near-real-time once ESRS is live)');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 3, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'BIR cross-checks transmitted data against filed returns');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who''s in scope, and since when', '[["Large Taxpayers (LTS)", "Covered from Phase 1 (RR 11-2025 / RR 26-2025)"], ["E-commerce & digital-platform businesses", "Covered regardless of size"], ["Exporters (VAT zero-rated)", "Covered"], ["CAS/POS users with e-invoicing capability", "Covered"], ["Registered Business Enterprises with tax incentives", "Covered"]]', 'Coverage is broader than "large taxpayers" alone -- any e-commerce business, regardless of size, is already in Phase 1 scope.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Exemptions and what''s still to come', '[["Micro enterprises", "Exempt (annual gross sales below PHP 3 million); may opt in voluntarily for incentives"], ["Remaining medium and small businesses", "Phase 2, no confirmed date -- contingent on BIR system readiness"], ["Non-resident, non-VAT-registered entities", "Outside scope"], ["Cross-border import verification", "A separate initiative (Pre-Border Technical Verification / Cross-Border E-Invoicing, JAO 001-2025) targets imports, not domestic sales invoicing"]]', 'Treat Phase 2 as directional, not dated -- the BIR has said it will follow once its own systems are ready, with no confirmed timeline yet.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔒 Closure risk for failing to transmit, not just a fine', NULL, NULL, 'Under NIRC Section 264-A, failing to transmit sales data to the EIS carries the higher of 1/10 of 1% of the prior year''s net income or PHP 10,000 per day -- and the BIR can order permanent business closure after 180 days of continued non-compliance. That is a materially harder consequence than a flat fine.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ A genuinely tiered penalty schedule', NULL, NULL, 'Beyond the transmission penalty, the NIRC as amended by the TRAIN Law and RR 13-2021 layers on separate sanctions: PHP 1,000-50,000 plus 2-4 years'' imprisonment for failing to issue a required e-invoice or misrepresenting a transaction; PHP 25,000 (first offense) or PHP 50,000 (second) for unregistered invoices or systems; and PHP 500,000-10,000,000 plus 2-10 years'' imprisonment for printing offenses or deliberately using sales-suppression ("zapper") software.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📅 A mandate with a documented history of slipping', NULL, NULL, 'This isn''t a mandate to treat as settled: the original pilot paused for roughly two years after 2022, and the Phase 1 deadline has already moved once, from March 2026 to December 2026. Build in a buffer rather than planning to the exact date.');
