INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Failure to issue a required e-invoice/receipt', 'PHP 1,000-50,000, plus 2-4 years'' imprisonment', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Invoice misrepresenting the transaction', 'PHP 1,000-50,000, plus 2-4 years'' imprisonment', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Unregistered invoices or systems (1st / 2nd offense)', 'PHP 25,000 / PHP 50,000 per unit', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Failure to transmit sales data to the EIS', 'Higher of 0.1% of prior-year net income or PHP 10,000/day', 'Permanent closure possible after 180 days');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Deliberate use of sales-suppression ("zapper") software', 'PHP 500,000-10,000,000, plus 2-10 years'' imprisonment', '—');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm whether your business is already in Phase 1 scope', 'Large Taxpayers, e-commerce/digital businesses of any size, exporters, and CAS/POS users are covered now -- the list is broader than "large taxpayers" alone, so check carefully rather than assuming it doesn''t apply.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Move off PDF invoicing before the deadline', 'RR 26-2025 is explicit that PDFs and other non-structured formats no longer qualify as valid e-invoices once Phase 1 applies -- confirm your invoicing or POS/CAS software can produce a genuinely structured, machine-readable format.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Register or update your CAS/POS permit with the BIR', 'Computerized accounting and point-of-sale systems used for e-invoicing need a current BIR permit-to-use -- an outdated or missing permit is its own compliance gap, separate from the invoicing format itself.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch for BIR guidance on the ESRS transmission platform', 'Real-time sales-data transmission depends on the BIR''s own Electronic Sales Reporting System being ready -- it was not yet fully live as of mid-2026, so expect further technical guidance before the deadline.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Build in a buffer -- this deadline has already moved once', 'The mandate was fully paused for about two years after its 2022 pilot, and the Phase 1 deadline already shifted from March 2026 to December 2026. Plan to be ready well before the date, not exactly on it.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Philippines';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you''re a micro enterprise, weigh voluntary opt-in against staying exempt', 'Micro enterprises (under PHP 3 million in annual gross sales) can access cost-deduction incentives by opting in early, even though they are not yet required to comply.');
